  function pressSimilarity(a,b){const na=norm(a),nb=norm(b);if(!na||!nb)return 0;if(na===nb)return 100;const aa=new Set(toks(na)),bb=new Set(toks(nb));if(!aa.size||!bb.size)return 0;let inter=0;for(const t of aa)if(bb.has(t))inter++;const dice=2*inter/(aa.size+bb.size);const coverage=inter/Math.min(aa.size,bb.size);return coverage>=.82?Math.round(dice*100):0;}
