  function load(id,meta){const hit=CACHE.get(id);if(hit&&Date.now()-hit.loadedAt<TTL)return Promise.resolve(hit);if(INFLIGHT.has(id))return INFLIGHT.get(id);const job=fetchPackage(id,meta).then(d=>{if(d)CACHE.set(id,d);return d;}).finally(()=>INFLIGHT.delete(id));INFLIGHT.set(id,job);return job;}
