  function hookEntry(){const entry=window.__ATLAS_ENTITY_ENTRY__;if(!entry||typeof entry.open!=='function')return false;if(entry.open.__atlasE360History===AUTHORITY)return true;const base=entry.open;const wrapped=async function(entityId,meta,...rest){const result=await base.apply(this,[entityId,meta,...rest]);const id=entityId||meta?.entity_id||selected();if(id)await openExpediente(id,meta);return result;};wrapped.__atlasE360History=AUTHORITY;wrapped.__atlasE360Base=base;entry.open=wrapped;return true;}
