  ensureCss();window.__ATLAS_ENTITY360_EXECUTIVE__={active:true,release:RELEASE,build:BUILD,variant:VARIANT,authority:AUTHORITY,sources:[MASTER,TAX,UAF,OSFL,SAN_SUM,SAN_EVENTS,SPEND,HISTORY,'Radar Prensa'],identityPolicy:'ENTITY_ID_OR_EXACT_NORMALIZED_RUT_ONLY',pressMatchPolicy:'STRICT_UNAMBIGUOUS_NAME_93_PLUS',missingSemantic:'MISSING_IS_NOT_ZERO_OR_ABSENCE',relationsVisible:false,authMutation:false,scoreMutation:false,cachePolicy:'MEMORY_ONLY',open:openExpediente,mount,hookEntry,clear:()=>CACHE.clear(),installedAt:new Date().toISOString()};window.__ATLAS_ENTITY360_HISTORY__={active:true,release:RELEASE,build:BUILD,variant:VARIANT,authority:AUTHORITY,relationsVisible:false,installedAt:new Date().toISOString()};hookEntry();installObserver();document.addEventListener('atlas:entity-workspace-ready',()=>{hookEntry();reconcile('workspace-ready');});document.addEventListener('atlas:entity-entry-ready',()=>{hookEntry();reconcile('entry-ready');});window.addEventListener('load',()=>{hookEntry();reconcile('startup');},{once:true});[0,180,550,1300,3000].forEach(ms=>setTimeout(()=>reconcile('startup'),ms));
